B.Vp=s([B.MR],t.J)
B.Ml=new A.cI("Barista",B.Vp)
B.Vg=s(["Hey\u2014stay with me. Can you hear me?","Who are you?"],t.s)
B.LI=new A.cn("Try to remember","intro_cannot_remember_name",!0,!1)
B.TS=s([B.LI],t.u)
B.MI=new A.c8(B.aa,B.Vg,null,null,null,B.TS)
B.V8=s([B.MI],t.J)
B.Mm=new A.cI("Concerned Stranger",B.V8)
B.Vr=s(["The fortress harbor opens, and the Royal Navy sails out to meet you.","Gilded warships spread across the channel beneath British flags, forming a wall between your fleet and the island.","Neither armada turns away."],t.s)
B.MU=new A.c8(B.aa,B.Vr,null,null,null,B.dC)
B.Vi=s([B.MU],t.J)
B.Mn=new A.cI("Narrator",B.Vi)
B.Td=s(["The cave trembles as something immense stirs beneath the black water.","A forest of tentacles rises from the depths, and a furious eye fixes upon your crew.","You were a fool to come here."],t.s)
B.M3=new A.cn("Face the Kraken","start_kraken_fight",!0,!1)
