B.US=s([B.MT],t.J)
B.Mq=new A.cI("Stranger",B.US)
B.Vs=s(["I was on my way to the docks when I found you. I was sure you were dead...","The doctor has been by to check on you. Your body, he says, will heal, but he cannot explain your memory loss.","Now that you are awake, do you remember anything about what happened to you?"],t.s)
B.LW=new A.cn("Try to remember","intro_recall_prince_face",!0,!1)
B.Vu=s([B.LW],t.u)
B.MM=new A.c8(B.aa,B.Vs,null,null,null,B.Vu)
B.VG=s([B.MM],t.J)
B.Mr=new A.cI("Mateo",B.VG)
B.Th=s(["Welcome aboard, sailor. I am Captain Lorenzo, and I assign bounties to crews bold enough to earn them.","A bounty is a promise: I name the target, you bring back proof, and the reward is yours.","I have a first contract waiting. Will you accept it?"],t.s)
B.M0=new A.cn("Accept first bounty","accept_italy_first_bounty",!0,!0)
B.LR=new A.cn("Not yet","close_dialogue",!0,!0)
